#include "fs.h"
#include "disk.h"
#include <assert.h>
#include <stdio.h>
#include <string.h>
#include <errno.h>
int main(void){char out[8192];assert(fs_format()==0);assert(fs_check()==0);assert(fs_mkdir("/docs",0)==0);assert(fs_mkdir("/docs/lab",0)==0);assert(fs_create("/docs/lab/notes.txt",100,0)==0);int fd=fs_open("/docs/lab/notes.txt",2,0);assert(fd>=0);char data[7000],back[7000];for(int i=0;i<7000;i++)data[i]=(char)('A'+i%26);assert(fs_write(fd,data,sizeof data,0)==sizeof data);memset(back,0,sizeof back);assert(fs_read(fd,back,sizeof back,0)==sizeof back);assert(!memcmp(data,back,sizeof data));assert(fs_close(fd)==0);assert(fs_check()==0);int cwd=fs_cd("/docs/lab",0);assert(cwd>=0);assert(fs_ls(".",cwd,out,sizeof out)>0);assert(fs_delete("/docs/lab/notes.txt",0)==0);assert(fs_check()==0);assert(fs_delete("/docs/lab",0)==0);assert(fs_delete("/docs",0)==0);assert(fs_check()==0);assert(fs_create("/persist.txt",7,0)==0);int pfd=fs_open("/persist.txt",2,0);assert(pfd>=0);const char *msg="survives restart";assert(fs_write(pfd,msg,strlen(msg),0)==(ssize_t)strlen(msg));assert(fs_close(pfd)==0);assert(fs_delete("/missing",0)==-ENOENT);assert(fs_mkdir("/nonempty",0)==0);assert(fs_create("/nonempty/child",0,0)==0);assert(fs_delete("/nonempty",0)==-ENOTEMPTY);assert(disk_save("disk.img")==0);disk_zero();assert(disk_load("disk.img")==0);assert(fs_mount()==0);assert(fs_check()==0);pfd=fs_open("/persist.txt",0,0);assert(pfd>=0);char persisted[64]={0};assert(fs_read(pfd,persisted,sizeof persisted,0)==(ssize_t)strlen(msg));assert(!strcmp(persisted,msg));assert(fs_close(pfd)==0);assert(fs_report(out,sizeof out)>0);puts("All filesystem tests passed.");puts(out);return 0;}
